<?php
declare(strict_types=1);

require dirname(__DIR__) . '/auth_store.php';
header('Content-Type: application/json; charset=UTF-8');
header('Cache-Control: no-store, no-cache, must-revalidate');

const TT_RET_FILE = TT_DATA_DIR . '/accounts.json';
const TT_RET_ACCOUNT_MASTER = __DIR__ . '/../accounts/accounting_master_v1.json';
const TT_RET_SETTLEMENT_POLICY = __DIR__ . '/../accounts/settlement_policy_v1.json';
const TT_RET_REALIZATION_POLICY = __DIR__ . '/../accounts/export_realization_policy_v1.json';

function rr_out(array $d,int $s=200): never {http_response_code($s);echo json_encode($d,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);exit;}
function rr_can(array $u): bool {if(($u['role']??'')==='Super Admin')return true;$p=$u['permissions']['Accounts']??null;if($p==='all')return true;if(!is_array($p))return false;if(in_array('Create',$p,true)||in_array('Edit',$p,true)||in_array('Approve',$p,true))return true;foreach($p as $a)if(is_array($a)&&(in_array('Create',$a,true)||in_array('Edit',$a,true)||in_array('Approve',$a,true)))return true;return false;}
function rr_entity(string $v): string {$v=strtoupper(trim($v));if(!in_array($v,['TTI','BRM'],true))rr_out(['ok'=>false,'error'=>'Retention outward remittance is available for TTI / BRM Pakistan books.'],422);return $v;}
function rr_store(): array {tt_ensure_data_dir();if(!is_file(TT_RET_FILE))return ['revision'=>0,'journals'=>[],'bankAccountSettings'=>[],'retentionRemittances'=>[]];$h=fopen(TT_RET_FILE,'r');if($h===false||!flock($h,LOCK_SH))throw new RuntimeException('Accounts storage unavailable.');try{$raw=stream_get_contents($h);}finally{flock($h,LOCK_UN);fclose($h);}$v=$raw?json_decode($raw,true):null;return is_array($v)?array_replace_recursive(['revision'=>0,'journals'=>[],'bankAccountSettings'=>[],'retentionRemittances'=>[]],$v):['revision'=>0,'journals'=>[],'bankAccountSettings'=>[],'retentionRemittances'=>[]];}
function rr_json(string $p): array {$r=is_file($p)?file_get_contents($p):false;$v=$r?json_decode($r,true):null;if(!is_array($v))throw new RuntimeException('Accounting policy unavailable.');return $v;}
function rr_catalog(): array {$out=[];foreach([TT_RET_ACCOUNT_MASTER,TT_RET_SETTLEMENT_POLICY,TT_RET_REALIZATION_POLICY] as $p){$m=rr_json($p);foreach((array)($m['chart']??$m['accounts']??[]) as $a)if(is_array($a)&&isset($a['code']))$out[(string)$a['code']]=$a;}return $out;}
function rr_entity_from_linked(string $v): string {$u=strtoupper($v);if(str_contains($u,'BRM')||str_contains($u,'BUKSH RICE'))return 'BRM';if(str_contains($u,'TTI')||str_contains($u,'TRANSTRADE INTERNATIONAL'))return 'TTI';return '';}
function rr_bank_master(): array {$m=tt_list_masters();$out=[];foreach((array)($m['banks']??[]) as $r){if(!is_array($r))continue;$v=array_values((array)($r['values']??[]));while(count($v)<14)$v[]='';$id=(string)($r['id']??'');$out[$id]=['id'=>$id,'accountType'=>(string)$v[0],'entity'=>rr_entity_from_linked((string)$v[1]),'title'=>(string)$v[3],'bank'=>(string)$v[4],'currency'=>strtoupper(trim((string)$v[7])),'accountNumber'=>(string)$v[8],'iban'=>(string)$v[9],'purpose'=>(string)$v[11]];}return $out;}
function rr_bank_bal(array $store,string $entity,string $id): array {$foreign=0.0;$functional=0.0;foreach((array)($store['journals']??[]) as $j){if(!is_array($j)||($j['status']??'')!=='Posted'||($j['entity']??'')!==$entity)continue;$jm=is_array($j['meta']??null)?$j['meta']:[];foreach((array)($j['lines']??[]) as $l){if(!is_array($l)||(string)($l['account']??'')!=='1110')continue;$bid=(string)($l['bankAccountId']??$jm['bankAccountId']??'');if($bid!==$id)continue;$foreign+=(float)($l['bankDebit']??0)-(float)($l['bankCredit']??0);$functional+=(float)($l['debit']??0)-(float)($l['credit']??0);}}$foreign=round($foreign,2);$functional=round($functional,2);return ['foreign'=>$foreign,'functionalPkr'=>$functional,'carryingRate'=>$foreign>0?round($functional/$foreign,6):0.0];}
function rr_payload(array $store,string $entity): array {$masters=rr_bank_master();$banks=[];foreach($masters as $id=>$b){if(($b['entity']??'')!==$entity||($b['accountType']??'')!=='Company Account'||($b['currency']??'')==='PKR')continue;$s=is_array($store['bankAccountSettings'][$id]??null)?$store['bankAccountSettings'][$id]:[];if(empty($s['active'])||empty($s['allowPayments']))continue;$banks[]=array_merge($b,rr_bank_bal($store,$entity,$id));}usort($banks,static fn($a,$b)=>strcmp((string)$a['bank'],(string)$b['bank'])?:strcmp((string)$a['title'],(string)$b['title']));$hist=[];foreach((array)($store['retentionRemittances']??[]) as $x)if(is_array($x)&&($x['entity']??'')===$entity)$hist[]=$x;usort($hist,static fn($a,$b)=>strcmp((string)$b['date'],(string)$a['date']));return ['ok'=>true,'entity'=>$entity,'banks'=>$banks,'history'=>array_slice($hist,0,30)];}
function rr_date(string $v): string {if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$v))rr_out(['ok'=>false,'error'=>'Valid remittance date is required.'],422);return $v;}
function rr_money(mixed $v,string $label,bool $zero=false): float {$n=round((float)$v,2);if($n<0||(!$zero&&$n<=0))rr_out(['ok'=>false,'error'=>$label.' must be '.($zero?'zero or greater':'greater than zero').'.'],422);return $n;}
function rr_next(array $items,string $prefix): string {$n=count($items)+1;do{$id=$prefix.'-'.gmdate('Y').'-'.str_pad((string)$n,6,'0',STR_PAD_LEFT);$n++;}while(isset($items[$id]));return $id;}
function rr_line(string $a,float $dr,float $cr,array $cat,array $x=[]): array {if(!isset($cat[$a]))rr_out(['ok'=>false,'error'=>'Accounting mapping '.$a.' is unavailable.'],422);return array_merge(['account'=>$a,'accountName'=>(string)($cat[$a]['name']??$a),'debit'=>round($dr,2),'credit'=>round($cr,2)],$x);}
function rr_allowed_target(string $type,string $account,array $cat): string {$type=strtoupper($type);if($type==='SUPPLIER_ADVANCE')return '1250';if($type==='EXISTING_PAYABLE'){if(!in_array($account,['2110','2120','2130','2140','2500'],true))rr_out(['ok'=>false,'error'=>'Select the payable/intercompany account being settled.'],422);return $account;}if($type==='DIRECT_EXPENSE'){if(!isset($cat[$account])||($cat[$account]['class']??'')!=='Expense'||in_array($account,['5100','5200','5300','5400','7100'],true))rr_out(['ok'=>false,'error'=>'Select an approved operating-expense account.'],422);return $account;}if($type==='FIXED_ASSET'){if(!in_array($account,['1510','1520','1530','1540'],true))rr_out(['ok'=>false,'error'=>'Select the fixed-asset category being purchased.'],422);return $account;}rr_out(['ok'=>false,'error'=>'Select a valid retention-remittance purpose.'],422);}

try{
  $user=tt_require_login();if(!tt_user_can_open_module($user,'Accounts'))rr_out(['ok'=>false,'error'=>'Accounts permission required.'],403);
  if($_SERVER['REQUEST_METHOD']==='GET'){$entity=rr_entity((string)($_GET['entity']??'TTI'));rr_out(rr_payload(rr_store(),$entity));}
  if($_SERVER['REQUEST_METHOD']!=='POST')rr_out(['ok'=>false,'error'=>'Method not allowed.'],405);if(!rr_can($user))rr_out(['ok'=>false,'error'=>'Accounts Create / Edit / Approve permission required.'],403);
  $body=json_decode(file_get_contents('php://input')?:'{}',true);if(!is_array($body)||!tt_verify_csrf((string)($body['csrf']??'')))rr_out(['ok'=>false,'error'=>'Your session expired. Refresh and try again.'],419);if((string)($body['action']??'')!=='post_remittance')rr_out(['ok'=>false,'error'=>'Unknown retention-remittance action.'],422);
  $entity=rr_entity((string)($body['entity']??''));$date=rr_date((string)($body['date']??''));$bankId=trim((string)($body['bankAccountId']??''));$payee=trim((string)($body['payee']??''));$reference=trim((string)($body['reference']??''));$purpose=trim((string)($body['purpose']??''));if($payee===''||$reference===''||$purpose==='')rr_out(['ok'=>false,'error'=>'Payee, remittance/reference number and purpose are required.'],422);$foreign=rr_money($body['foreignAmount']??0,'Remittance foreign amount');$rate=rr_money($body['transactionRate']??0,'Transaction / remittance rate');$type=strtoupper(trim((string)($body['settlementType']??'')));$targetReq=trim((string)($body['targetAccount']??''));$payableCarrying=rr_money($body['payableCarryingPkr']??0,'Payable carrying amount',true);$evidence=trim((string)($body['evidenceRef']??''));$notes=trim((string)($body['notes']??''));$charges=[];$chargeForeign=0.0;foreach((array)($body['charges']??[]) as $c){if(!is_array($c))continue;$amt=rr_money($c['foreignAmount']??0,'Remittance charge amount');$desc=trim((string)($c['description']??''));if($desc==='')rr_out(['ok'=>false,'error'=>'Explain every remittance charge.'],422);$charges[]=['description'=>$desc,'foreignAmount'=>$amt];$chargeForeign+=$amt;}$chargeForeign=round($chargeForeign,2);
  tt_ensure_data_dir();$h=fopen(TT_RET_FILE,'c+');if($h===false||!flock($h,LOCK_EX))throw new RuntimeException('Accounts storage unavailable.');
  try{rewind($h);$raw=stream_get_contents($h);$store=$raw?json_decode($raw,true):null;if(!is_array($store))$store=[];$store=array_replace_recursive(['revision'=>0,'journals'=>[],'bankAccountSettings'=>[],'retentionRemittances'=>[]],$store);$masters=rr_bank_master();$bank=$masters[$bankId]??null;if(!is_array($bank)||($bank['entity']??'')!==$entity||($bank['accountType']??'')!=='Company Account'||($bank['currency']??'')==='PKR')rr_out(['ok'=>false,'error'=>'Select an active foreign-currency retention/company bank account.'],422);$set=is_array($store['bankAccountSettings'][$bankId]??null)?$store['bankAccountSettings'][$bankId]:[];if(empty($set['active'])||empty($set['allowPayments']))rr_out(['ok'=>false,'error'=>'Selected foreign-currency bank is not enabled for payments in Accounts.'],422);$bal=rr_bank_bal($store,$entity,$bankId);$totalForeign=round($foreign+$chargeForeign,2);if($totalForeign>$bal['foreign']+.01)rr_out(['ok'=>false,'error'=>'Insufficient '.$bank['currency'].' balance. Remittance plus charges require '.$bank['currency'].' '.number_format($totalForeign,2).' but the book balance is '.$bank['currency'].' '.number_format($bal['foreign'],2).'.'],422);if($bal['carryingRate']<=0)rr_out(['ok'=>false,'error'=>'Retention bank has no usable PKR carrying rate. Reconcile/open the foreign bank balance before remitting.'],422);$cat=rr_catalog();$target=rr_allowed_target($type,$targetReq,$cat);$mainPkr=$type==='EXISTING_PAYABLE'?$payableCarrying:round($foreign*$rate,2);if($type==='EXISTING_PAYABLE'&&$mainPkr<=0)rr_out(['ok'=>false,'error'=>'Enter the PKR carrying amount of the payable being settled.'],422);$chargePkr=round($chargeForeign*$rate,2);$bankCarry=round($totalForeign*$bal['carryingRate'],2);$lines=[rr_line($target,$mainPkr,0,$cat,['payee'=>$payee,'settlementType'=>$type,'foreignAmount'=>$foreign,'currency'=>$bank['currency'],'transactionRate'=>$rate])];foreach($charges as $c)$lines[]=rr_line('6810',round($c['foreignAmount']*$rate,2),0,$cat,['chargeDescription'=>$c['description'],'foreignAmount'=>$c['foreignAmount'],'currency'=>$bank['currency'],'transactionRate'=>$rate]);$lines[]=rr_line('1110',0,$bankCarry,$cat,['bankAccountId'=>$bankId,'bankName'=>$bank['bank'],'bankAccountTitle'=>$bank['title'],'currency'=>$bank['currency'],'bankDebit'=>0,'bankCredit'=>$totalForeign]);$dr=round(array_sum(array_column($lines,'debit')),2);$cr=round(array_sum(array_column($lines,'credit')),2);$diff=round($dr-$cr,2);if($diff>0)$lines[]=rr_line('7100',0,$diff,$cat,['fxDirection'=>'Gain']);elseif($diff<0)$lines[]=rr_line('7100',abs($diff),0,$cat,['fxDirection'=>'Loss']);$dr=round(array_sum(array_column($lines,'debit')),2);$cr=round(array_sum(array_column($lines,'credit')),2);if(abs($dr-$cr)>.01)throw new RuntimeException('Retention remittance journal did not balance.');$id=rr_next((array)$store['retentionRemittances'],'ROR');$jid=rr_next((array)$store['journals'],'AUTO');$meta=['retentionRemittanceId'=>$id,'bankAccountId'=>$bankId,'bankName'=>$bank['bank'],'currency'=>$bank['currency'],'foreignAmount'=>$foreign,'chargeForeignAmount'=>$chargeForeign,'totalForeignBankDebit'=>$totalForeign,'transactionRate'=>$rate,'bankCarryingRate'=>$bal['carryingRate'],'bankCarryingPkr'=>$bankCarry,'settlementType'=>$type,'targetAccount'=>$target,'payee'=>$payee,'purpose'=>$purpose,'charges'=>$charges,'evidenceRef'=>$evidence,'notes'=>$notes];$store['journals'][$jid]=['id'=>$jid,'entity'=>$entity,'date'=>$date,'sourceType'=>'RETENTION_OUTWARD_REMITTANCE','reference'=>$reference,'narration'=>'Retention outward remittance — '.$payee.' — '.$purpose,'lines'=>$lines,'totalDebit'=>$dr,'totalCredit'=>$cr,'status'=>'Posted','meta'=>$meta,'createdAt'=>gmdate('c'),'createdBy'=>(string)($user['full_name']??$user['username']??'Accounts'),'userId'=>(int)($user['id']??0),'reversalOf'=>null];$row=['id'=>$id,'entity'=>$entity,'date'=>$date,'bankAccountId'=>$bankId,'bankName'=>$bank['bank'],'currency'=>$bank['currency'],'foreignAmount'=>$foreign,'charges'=>$charges,'chargeForeignAmount'=>$chargeForeign,'totalForeignDebit'=>$totalForeign,'transactionRate'=>$rate,'bankCarryingRate'=>$bal['carryingRate'],'payee'=>$payee,'purpose'=>$purpose,'reference'=>$reference,'settlementType'=>$type,'targetAccount'=>$target,'journalId'=>$jid,'evidenceRef'=>$evidence,'notes'=>$notes,'status'=>'Accounts Approved / Posted','createdAt'=>gmdate('c'),'createdBy'=>(string)($user['full_name']??$user['username']??'Accounts')];$store['retentionRemittances'][$id]=$row;$store['revision']=(int)($store['revision']??0)+1;rewind($h);ftruncate($h,0);fwrite($h,json_encode($store,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR));fflush($h);
  }finally{flock($h,LOCK_UN);fclose($h);}rr_out(rr_payload($store,$entity)+['remittance'=>$row,'journal'=>$store['journals'][$jid],'revision'=>$store['revision']]);
}catch(Throwable $e){rr_out(['ok'=>false,'error'=>'The retention outward remittance could not be posted.'],500);}
